import React, { useEffect, useMemo, useState } from 'react';
import { toast } from 'react-toastify';
import {
  FiPlus,
  FiTrash2,
  FiEdit2,
  FiImage,
  FiUploadCloud,
  FiX,
  FiStar,
  FiSearch,
  FiFilter,
  FiLayers,
  FiCheckCircle,
  FiEye,
} from 'react-icons/fi';

import api, { getApiErrorMessage } from '../../services/api';
import { getImageUrl } from '../../utils/helpers';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';
import AdminTable from '../common/AdminTable';
import { useLanguage } from '../../contexts/LanguageContext';

const categoryOptions = [
  { en: 'School Activities', km: 'សកម្មភាពសាលា' },
  { en: 'Classroom', km: 'ថ្នាក់រៀន' },
  { en: 'Graduation', km: 'ពិធីបញ្ចប់ការសិក្សា' },
  { en: 'Trips', km: 'ដំណើរកម្សាន្ត' },
  { en: 'Special Events', km: 'ព្រឹត្តិការណ៍ពិសេស' },
  { en: 'Social Activities and Leadership', km: 'សកម្មភាពសង្គម និងភាពជាអ្នកដឹកនាំ' },
  { en: 'Education', km: 'ការអប់រំ' },
  { en: 'Workshops', km: 'សិក្ខាសាលា' },
  { en: 'Student Activities', km: 'សកម្មភាពសិស្ស' },
  { en: 'Learning Activities', km: 'សកម្មភាពសិក្សា' },
  { en: 'Technology and Education', km: 'បច្ចេកវិទ្យា និងការអប់រំ' },
  { en: 'Youth and Leadership', km: 'យុវជន និងភាពជាអ្នកដឹកនាំ' },
  { en: 'Social Activities', km: 'សកម្មភាពសង្គម' },
  { en: 'Knowledge Sharing', km: 'ចែករំលែកចំណេះដឹង' },
  { en: 'Teachers', km: 'គ្រូបង្រៀន' },
  { en: 'School Community', km: 'សហគមន៍សាលា' },
  { en: 'Study Tours', km: 'ទស្សនកិច្ចសិក្សា' },
  { en: 'Entrepreneurship', km: 'សហគ្រិនភាព' },
  { en: 'School News', km: 'ព័ត៌មានសាលា' },
];

const initialForm = {
  title_en: '',
  category_en: '',
  description_en: '',
  title_km: '',
  category_km: '',
  description_km: '',
  is_featured: false,
  order: 0,
};

const AdminGallery = () => {
  const { t, language } = useLanguage();
  const isKhmer = language === 'km' || language === 'kh';

  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingImage, setEditingImage] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState('');
  const [previewModalImg, setPreviewModalImg] = useState(null);

  // Search & Filter
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('ALL');

  const [formData, setFormData] = useState({ ...initialForm });

  const getLocalizedValue = (item, field) => {
    if (!item) return '';
    if (isKhmer) {
      return item[`${field}_km`] || item[`${field}_en`] || '';
    }
    return item[`${field}_en`] || item[`${field}_km`] || '';
  };

  const fetchImages = async () => {
    try {
      setLoading(true);
      const response = await api.get('/api/gallery/');
      setImages(Array.isArray(response.data) ? response.data : []);
    } catch (error) {
      console.error('Gallery error:', error);
      toast.error(getApiErrorMessage(error, isKhmer ? 'មិនអាចទាញទិន្នន័យរូបភាពបានទេ' : 'Failed to load gallery images'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchImages();
  }, []);

  useEffect(() => {
    return () => {
      if (imagePreview && imagePreview.startsWith('blob:')) {
        URL.revokeObjectURL(imagePreview);
      }
    };
  }, [imagePreview]);

  const handleOpenCreate = () => {
    setEditingImage(null);
    setFormData({ ...initialForm });
    setImageFile(null);
    setImagePreview('');
    setModalOpen(true);
  };

  const handleEdit = (img) => {
    setEditingImage(img);
    setFormData({
      title_en: img.title_en || '',
      category_en: img.category_en || '',
      description_en: img.description_en || '',
      title_km: img.title_km || '',
      category_km: img.category_km || '',
      description_km: img.description_km || '',
      is_featured: Boolean(img.is_featured),
      order: img.order || 0,
    });
    setImageFile(null);
    setImagePreview(img.image_url ? getImageUrl(img.image_url) : '');
    setModalOpen(true);
  };

  const handleDelete = async (id) => {
    const confirmed = window.confirm(
      isKhmer ? 'តើអ្នកប្រាកដជាចង់លុបរូបភាពនេះមែនទេ?' : 'Are you sure you want to delete this image?'
    );
    if (!confirmed) return;

    try {
      await api.delete(`/api/gallery/${id}`);
      toast.success(isKhmer ? 'បានលុបរូបភាពដោយជោគជ័យ' : 'Image deleted successfully');
      setImages((prev) => prev.filter((item) => item.id !== id));
    } catch (error) {
      console.error('Delete error:', error);
      toast.error(getApiErrorMessage(error, isKhmer ? 'មិនអាចលុបរូបភាពបានទេ' : 'Failed to delete image'));
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      if (!file.type.startsWith('image/')) {
        toast.error(isKhmer ? 'សូមជ្រើសរើស File រូបភាពដែលត្រឹមត្រូវ' : 'Please select a valid image file');
        return;
      }
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!editingImage && !imageFile) {
      toast.error(isKhmer ? 'សូមជ្រើសរើសរូបភាពដើម្បី Upload' : 'Please select an image file to upload');
      return;
    }

    try {
      setSubmitting(true);
      const data = new FormData();

      data.append('title_en', formData.title_en.trim());
      data.append('category_en', formData.category_en.trim());
      data.append('description_en', formData.description_en.trim());
      data.append('title_km', formData.title_km.trim());
      data.append('category_km', formData.category_km.trim());
      data.append('description_km', formData.description_km.trim());
      data.append('is_featured', formData.is_featured ? 'true' : 'false');
      data.append('order', String(formData.order || 0));

      if (imageFile) {
        data.append('file', imageFile);
      }

      if (editingImage) {
        await api.put(`/api/gallery/${editingImage.id}`, data, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success(isKhmer ? 'បានកែប្រែរូបភាពដោយជោគជ័យ' : 'Image updated successfully');
      } else {
        await api.post('/api/gallery/', data, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success(isKhmer ? 'បានបញ្ចូលរូបភាពថ្មីដោយជោគជ័យ' : 'Image uploaded successfully');
      }

      setModalOpen(false);
      await fetchImages();
    } catch (error) {
      console.error('Submit error:', error);
      toast.error(getApiErrorMessage(error, isKhmer ? 'មិនអាចរក្សាទុកទិន្នន័យបានទេ' : 'Failed to save image'));
    } finally {
      setSubmitting(false);
    }
  };

  // Filtered images
  const filteredImages = useMemo(() => {
    return images.filter((img) => {
      const titleEn = (img.title_en || '').toLowerCase();
      const titleKm = (img.title_km || '').toLowerCase();
      const catEn = img.category_en || '';
      const catKm = img.category_km || '';
      const term = searchTerm.toLowerCase();

      const matchesSearch = !searchTerm || titleEn.includes(term) || titleKm.includes(term);
      const matchesCategory =
        selectedCategory === 'ALL' || catEn === selectedCategory || catKm === selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }, [images, searchTerm, selectedCategory]);

  // Statistics
  const featuredCount = useMemo(() => images.filter((i) => i.is_featured).length, [images]);
  const categoriesCount = useMemo(
    () => new Set(images.map((i) => getLocalizedValue(i, 'category')).filter(Boolean)).size,
    [images, isKhmer]
  );

  // Table Columns
  const columns = [
    {
      key: 'image',
      label: isKhmer ? 'រូបភាព' : 'Image',
      render: (_, row) => {
        const fullUrl = row.image_url ? getImageUrl(row.image_url) : '/default-avatar.png';
        const title = getLocalizedValue(row, 'title') || 'Gallery Photo';
        return (
          <div className="flex items-center gap-3">
            <div
              className="relative w-16 h-12 rounded-xl overflow-hidden bg-slate-100 border border-slate-200 flex-shrink-0 cursor-pointer group"
              onClick={() => setPreviewModalImg(fullUrl)}
            >
              <img
                src={fullUrl}
                alt={title}
                className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-110"
                onError={(e) => {
                  e.currentTarget.src = '/default-avatar.png';
                }}
              />
              <div className="absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white">
                <FiEye size={16} />
              </div>
            </div>
          </div>
        );
      },
    },
    {
      key: 'title',
      label: isKhmer ? 'ចំណងជើង' : 'Title',
      render: (_, row) => {
        const primaryTitle = getLocalizedValue(row, 'title') || (isKhmer ? 'គ្មានចំណងជើង' : 'Untitled');
        const secondaryTitle = isKhmer ? row.title_en : row.title_km;
        const description = getLocalizedValue(row, 'description');

        return (
          <div className="max-w-md">
            <p className="font-bold text-slate-900 text-sm">{primaryTitle}</p>
            {secondaryTitle && secondaryTitle !== primaryTitle && (
              <p className="text-xs text-slate-400 font-medium">{secondaryTitle}</p>
            )}
            {description && (
              <p className="text-xs text-slate-500 line-clamp-1 mt-0.5">{description}</p>
            )}
          </div>
        );
      },
    },
    {
      key: 'category',
      label: isKhmer ? 'ប្រភេទ' : 'Category',
      render: (_, row) => {
        const catName = getLocalizedValue(row, 'category') || (isKhmer ? 'ទូទៅ' : 'General');
        return (
          <span className="inline-flex items-center px-2.5 py-1 rounded-full text-xs font-semibold bg-blue-50 text-[#2563EB] border border-blue-100">
            {catName}
          </span>
        );
      },
    },
    {
      key: 'order',
      label: isKhmer ? 'លំដាប់' : 'Order',
      render: (_, row) => (
        <span className="font-bold text-slate-700 text-xs px-2 py-0.5 bg-slate-100 rounded-md">
          {row.order ?? 0}
        </span>
      ),
    },
    {
      key: 'featured',
      label: isKhmer ? 'ពិសេស' : 'Featured',
      render: (_, row) => (
        row.is_featured ? (
          <span className="inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold bg-amber-50 text-amber-600 border border-amber-200">
            <FiStar size={12} className="fill-amber-500 text-amber-500" />
            {isKhmer ? 'ពិសេស' : 'Featured'}
          </span>
        ) : (
          <span className="text-slate-300 font-bold">-</span>
        )
      ),
    },
    {
      key: 'actions',
      label: isKhmer ? 'សកម្មភាព' : 'Actions',
      render: (_, row) => (
        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => handleEdit(row)}
            className="w-8 h-8 rounded-lg bg-blue-50 text-[#2563EB] hover:bg-[#2563EB] hover:text-white flex items-center justify-center transition-colors shadow-sm"
            title={isKhmer ? 'កែប្រែ' : 'Edit'}
          >
            <FiEdit2 size={14} />
          </button>
          <button
            type="button"
            onClick={() => handleDelete(row.id)}
            className="w-8 h-8 rounded-lg bg-rose-50 text-rose-600 hover:bg-rose-600 hover:text-white flex items-center justify-center transition-colors shadow-sm"
            title={isKhmer ? 'លុប' : 'Delete'}
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div className={`p-4 md:p-6 lg:p-8 space-y-6 ${isKhmer ? 'font-khmer' : ''}`}>

      {/* Top Header Card */}
      <AdminCard>
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-xl sm:text-2xl font-extrabold text-slate-900 flex items-center gap-2.5">
              <FiImage className="text-[#2563EB]" />
              <span>{isKhmer ? 'គ្រប់គ្រងវិចិត្រសាលរូបភាព' : 'Gallery Management'}</span>
            </h1>
            <p className="text-xs sm:text-sm text-slate-500 font-medium mt-1">
              {isKhmer
                ? 'បន្ថែម កែប្រែ និងលុបរូបភាពសកម្មភាពផ្សេងៗរបស់សាលា។'
                : 'Upload, manage, and organize school activity and campus photographs.'}
            </p>
          </div>

          <button
            type="button"
            onClick={handleOpenCreate}
            className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-[#2563EB] hover:bg-[#1D4ED8] text-white font-bold text-xs sm:text-sm shadow-sm transition-all active:scale-95 flex-shrink-0"
          >
            <FiPlus size={16} />
            <span>{isKhmer ? 'បន្ថែមរូបភាពថ្មី' : 'Upload Image'}</span>
          </button>
        </div>

        {/* Stats Row */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mt-6 pt-6 border-t border-slate-100">
          <div className="p-4 rounded-xl bg-slate-50 border border-slate-200/60 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-slate-500">{isKhmer ? 'រូបភាពសរុប' : 'Total Photos'}</p>
              <p className="text-xl font-extrabold text-[#1E3A8A] mt-0.5">{images.length}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-blue-50 text-[#2563EB] flex items-center justify-center">
              <FiImage size={20} />
            </div>
          </div>

          <div className="p-4 rounded-xl bg-slate-50 border border-slate-200/60 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-slate-500">{isKhmer ? 'រូបភាពពិសេស' : 'Featured Photos'}</p>
              <p className="text-xl font-extrabold text-[#1E3A8A] mt-0.5">{featuredCount}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center">
              <FiStar size={20} />
            </div>
          </div>

          <div className="p-4 rounded-xl bg-slate-50 border border-slate-200/60 flex items-center justify-between">
            <div>
              <p className="text-xs font-semibold text-slate-500">{isKhmer ? 'ប្រភេទសរុប' : 'Categories'}</p>
              <p className="text-xl font-extrabold text-[#1E3A8A] mt-0.5">{categoriesCount}</p>
            </div>
            <div className="w-10 h-10 rounded-xl bg-indigo-50 text-indigo-600 flex items-center justify-center">
              <FiLayers size={20} />
            </div>
          </div>
        </div>
      </AdminCard>

      {/* Filter & Search Bar */}
      <AdminCard>
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-4">
          {/* Search Input */}
          <div className="relative flex-1">
            <FiSearch className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
            <input
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder={isKhmer ? 'ស្វែងរកតាមចំណងជើងរូបភាព...' : 'Search by image title...'}
              className="w-full pl-10 pr-4 py-2.5 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none transition-colors"
            />
            {searchTerm && (
              <button
                type="button"
                onClick={() => setSearchTerm('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
              >
                <FiX size={14} />
              </button>
            )}
          </div>

          {/* Category Filter Dropdown */}
          <div className="flex items-center gap-2">
            <FiFilter className="text-slate-400 flex-shrink-0" size={16} />
            <select
              value={selectedCategory}
              onChange={(e) => setSelectedCategory(e.target.value)}
              className="px-3.5 py-2.5 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none font-semibold text-slate-700 transition-colors"
            >
              <option value="ALL">{isKhmer ? 'ប្រភេទទាំងអស់' : 'All Categories'}</option>
              {categoryOptions.map((cat) => (
                <option key={cat.en} value={cat.en}>
                  {isKhmer ? cat.km : cat.en}
                </option>
              ))}
            </select>
          </div>
        </div>
      </AdminCard>

      {/* Table / List View */}
      <AdminTable columns={columns} data={filteredImages} loading={loading} />

      {/* Upload / Edit Modal */}
      <AdminModal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        title={
          editingImage
            ? (isKhmer ? 'កែប្រែរូបភាពវិចិត្រសាល' : 'Edit Gallery Photo')
            : (isKhmer ? 'បញ្ចូលរូបភាពថ្មីក្នុងវិចិត្រសាល' : 'Upload Gallery Photo')
        }
      >
        <form onSubmit={handleSubmit} className="space-y-4">
          {/* File Upload Area */}
          <div>
            <label className="block text-xs font-bold text-slate-700 mb-1.5">
              {isKhmer ? 'ជ្រើសរើសរូបភាព (Image File)' : 'Upload Image File'} *
            </label>
            <div className="flex items-center gap-4">
              <label className="flex-1 flex flex-col items-center justify-center p-5 border-2 border-dashed border-slate-300 hover:border-[#2563EB] rounded-2xl cursor-pointer bg-slate-50/60 hover:bg-blue-50/30 transition-all">
                <FiUploadCloud size={28} className="text-[#2563EB] mb-2" />
                <span className="text-xs font-bold text-slate-700">
                  {imageFile ? imageFile.name : (isKhmer ? 'ចុចទីនេះដើម្បីជ្រើសរើសរូបភាព' : 'Click to select an image')}
                </span>
                <span className="text-[11px] text-slate-400 mt-0.5">PNG, JPG, WEBP up to 10MB</span>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileChange}
                  className="hidden"
                />
              </label>

              {imagePreview && (
                <div className="relative w-24 h-24 rounded-2xl overflow-hidden border border-slate-200 bg-slate-100 flex-shrink-0">
                  <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                  <button
                    type="button"
                    onClick={() => { setImageFile(null); setImagePreview(''); }}
                    className="absolute top-1 right-1 w-6 h-6 rounded-full bg-slate-900/80 text-white flex items-center justify-center hover:bg-red-600"
                  >
                    <FiX size={12} />
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* Bilingual Titles */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">
                {isKhmer ? 'ចំណងជើង (ខ្មែរ)' : 'Title (Khmer)'}
              </label>
              <input
                type="text"
                value={formData.title_km}
                onChange={(e) => setFormData({ ...formData, title_km: e.target.value })}
                placeholder="ឧ. សកម្មភាពសិក្ខាសាលា..."
                className="w-full px-3.5 py-2.5 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">
                {isKhmer ? 'ចំណងជើង (អង់គ្លេស)' : 'Title (English)'}
              </label>
              <input
                type="text"
                value={formData.title_en}
                onChange={(e) => setFormData({ ...formData, title_en: e.target.value })}
                placeholder="e.g. Workshop Activity..."
                className="w-full px-3.5 py-2.5 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none"
              />
            </div>
          </div>

          {/* Category Dropdowns */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">
                {isKhmer ? 'ប្រភេទ (ខ្មែរ)' : 'Category (Khmer)'}
              </label>
              <select
                value={formData.category_km}
                onChange={(e) => {
                  const selected = categoryOptions.find((c) => c.km === e.target.value);
                  setFormData({
                    ...formData,
                    category_km: e.target.value,
                    category_en: selected ? selected.en : formData.category_en,
                  });
                }}
                className="w-full px-3.5 py-2.5 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none"
              >
                <option value="">-- ជ្រើសរើសប្រភេទ --</option>
                {categoryOptions.map((c) => (
                  <option key={c.km} value={c.km}>{c.km}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">
                {isKhmer ? 'ប្រភេទ (អង់គ្លេស)' : 'Category (English)'}
              </label>
              <select
                value={formData.category_en}
                onChange={(e) => {
                  const selected = categoryOptions.find((c) => c.en === e.target.value);
                  setFormData({
                    ...formData,
                    category_en: e.target.value,
                    category_km: selected ? selected.km : formData.category_km,
                  });
                }}
                className="w-full px-3.5 py-2.5 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none"
              >
                <option value="">-- Select Category --</option>
                {categoryOptions.map((c) => (
                  <option key={c.en} value={c.en}>{c.en}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Descriptions */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">
                {isKhmer ? 'ពិពណ៌នា (ខ្មែរ)' : 'Description (Khmer)'}
              </label>
              <textarea
                rows={2}
                value={formData.description_km}
                onChange={(e) => setFormData({ ...formData, description_km: e.target.value })}
                placeholder="ព័ត៌មានបន្ថែមអំពីរូបភាព..."
                className="w-full px-3.5 py-2 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none resize-none"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-700 mb-1">
                {isKhmer ? 'ពិពណ៌នា (អង់គ្លេស)' : 'Description (English)'}
              </label>
              <textarea
                rows={2}
                value={formData.description_en}
                onChange={(e) => setFormData({ ...formData, description_en: e.target.value })}
                placeholder="Additional details..."
                className="w-full px-3.5 py-2 text-xs sm:text-sm bg-slate-50 border border-slate-200 rounded-xl focus:bg-white focus:border-[#2563EB] focus:outline-none resize-none"
              />
            </div>
          </div>

          {/* Order & Featured */}
          <div className="flex items-center justify-between pt-2">
            <div className="flex items-center gap-3">
              <label className="text-xs font-bold text-slate-700">{isKhmer ? 'លំដាប់បង្ហាញ:' : 'Sort Order:'}</label>
              <input
                type="number"
                value={formData.order}
                onChange={(e) => setFormData({ ...formData, order: parseInt(e.target.value, 10) || 0 })}
                className="w-20 px-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-lg text-center font-bold"
              />
            </div>

            <label className="flex items-center gap-2 text-xs font-bold text-slate-700 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={formData.is_featured}
                onChange={(e) => setFormData({ ...formData, is_featured: e.target.checked })}
                className="w-4 h-4 rounded text-[#2563EB] focus:ring-[#2563EB]"
              />
              <span>{isKhmer ? 'កំណត់ជារូបភាពពិសេស (Featured)' : 'Featured Photo'}</span>
            </label>
          </div>

          {/* Modal Actions */}
          <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-100">
            <button
              type="button"
              onClick={() => setModalOpen(false)}
              className="px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-bold transition-colors"
            >
              {isKhmer ? 'បោះបង់' : 'Cancel'}
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="px-5 py-2 rounded-xl bg-[#2563EB] hover:bg-[#1D4ED8] text-white text-xs font-bold transition-colors shadow-sm disabled:opacity-50"
            >
              {submitting
                ? (isKhmer ? 'កំពុងរក្សាទុក...' : 'Saving...')
                : (isKhmer ? 'រក្សាទុក' : 'Save Photo')}
            </button>
          </div>
        </form>
      </AdminModal>

      {/* Full Image Preview Modal */}
      {previewModalImg && (
        <div
          className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4"
          onClick={() => setPreviewModalImg(null)}
        >
          <div className="relative max-w-4xl max-h-[90vh] overflow-hidden rounded-2xl bg-black">
            <img src={previewModalImg} alt="Preview" className="max-w-full max-h-[85vh] object-contain mx-auto" />
            <button
              type="button"
              onClick={() => setPreviewModalImg(null)}
              className="absolute top-3 right-3 w-8 h-8 rounded-full bg-white/20 text-white flex items-center justify-center hover:bg-red-600 transition-colors"
            >
              <FiX size={18} />
            </button>
          </div>
        </div>
      )}

    </div>
  );
};

export default AdminGallery;
